    "intro": "王粲（177年—217年2月17日），字仲宣。山阳郡高平县（今山东省微山县两城镇）人。东汉末年文学家、官员，“建安七子”之一，太尉王龚曾孙、司空王畅之孙。 王粲自少即有才名，为学者蔡邕所赏识。司徒想征辟他为黄门侍郎，王粲因为长安局势混乱，没有赴任，选择南下依附荆州牧刘表，但未受到刘表重用。 建安十三年（208年），丞相曹操南征荆州，刘表之子刘琮举州投降，王粲也归于曹操，深得曹氏父子信赖，被赐爵关内侯。建安十八年（213年），魏王国建立，王粲任侍中。建安二十二年（216年），随曹操南征孙权，于北还途中病逝，终年四十一岁。 王粲善属文，其诗赋为建安七子之冠，又与曹植并称“曹王”。著《英雄记》，《三国志》记王粲著诗、赋、论、议近60篇 ，《隋书·经籍志》著录有文集十一卷。明人张溥辑有《王侍中集》。",
