    "thumb": "https://www.sanguosha.cn/storage/uploads/images/pic_index/559.png",
    "intro": "赵累，三国时蜀汉将领，隶属于关羽。建安后期，赵累任关羽所置的都督一职。 赵累为人忠诚廉直，为关羽军前都督、粮料官。关羽攻打襄阳时，王甫举荐赵累为都督驻守荆州，但是关羽不听。关羽败走麦城，赵累在随关羽突围时死于乱军之中。 王甫（？—222年），字国山，广汉郪（今四川三台县）人，三国时期蜀汉重臣。刘璋时，为益州书佐，之后归降刘备，先后担任绵竹令、荆州议曹从事。 在关羽攻拔襄阳后，王甫提醒关羽防备吕蒙的袭击，关羽因此建造烽火台；随后王甫举荐忠正廉直的赵累取代潘浚总督荆州，关羽并不采纳。后来关羽计划逃出麦城，让王甫与周仓据守麦城，王甫劝关羽走大路。关羽被擒杀之后，吴军在城下劝王甫、周仓等人投降，王甫得知关羽的死讯时，堕城而死，以身殉义。",
