    "thumb": "https://www.sanguosha.cn/storage/uploads/images/pic_index/570.jpg",
    "intro": "华歆[xīn]（157年－232年1月30日），字子鱼，平原郡高唐县（今山东省高唐县）人，汉族。 汉末三国时期名士、重臣。华歆早年拜太尉陈球为师，与卢植、郑玄、管宁等为同门 ，又与管宁、邴原共称一龙，华歆为龙头。汉灵帝时期，举孝廉出身，任郎中，因病去官。得到大将军何进征召，出任尚书郎，出任豫章太守，甚得民心。归顺小霸王孙策，成为上宾。官渡之战时，出任议郎、司空参军，累迁尚书、侍中、尚书令。曹操讨伐孙权时，担任军师。曹操封王后，担任魏国御史大夫，支持曹丕即位，出任魏国相国，册封安乐乡侯。曹魏建立后，担任司徒。魏明帝即位，升任太尉，晋封博平县侯。太和五年（232年1月），病逝，享年七十五岁，谥号为敬。",
