    "intro": "曹丕，字子桓，沛国谯县（今安徽省亳州市）人。 三国时期政治家、文学家，曹魏开国皇帝。文武双全，博览经传，通晓诸子百家学说，累迁五官中郎将。建安二十二年（217年），成为魏国世子。建安二十五年（220年），曹操去世后，继任丞相、魏王。同年代汉称帝，建立曹魏 。在位期间，采纳吏部尚书陈群的意见，制定实施九品中正制，成为魏晋南北朝时期主要的选官制度，平定了青州、徐州一带的割据势力，最终完成了北方地区的统一。对外平定边患，击退鲜卑，和匈奴、氐、羌等外夷修好，恢复在西域的建置。黄初七年五月丁巳日，曹丕病逝于洛阳，时年四十岁，谥号文皇帝，庙号高祖，安葬于首阳陵。曹丕于诗、赋、文学皆有成就，擅长于五言诗，与其父曹操和弟曹植并称“建安三曹”，今存《魏文帝集》二卷。著有《典论》，当中的《论文》是中国文学史上第一部有系统的文学批评专论作品。",
