    "intro": "司马昭，字子上，早年受荫庇于父兄，不慕霸业。及父兄殂谢，昭承继家业，负谋魏自立之责，野心渐起，虽心气才学不及父兄，仍殚竭经营大业，笼人心，除异己，欲令百官贵胄俯首。唯诸葛诞拥兵自重，独据淮南，昭恐其不利于宗族大业，欲除之以建战功，威服四方。昭乃使计逼反诸葛诞，又担忧曹髦为乱后方，乃挟之以同征淮南，临戎除逆。昭惯施权谋，建高墙于寿春城外，围而不攻，为彰显恩德，围城期间每有归降者，皆宽赦旧罪。昭收服叛逃倒戈者众，诞、鸯等屡次突围皆大败而归。昭自觉宗族夙愿将成之际，雷声滚滚，大雨倾盆，围墙塌落，魏军困于泥沼，诸葛诞趁势突围，文鸯乘乱欲劫天子。昭恐宗族大业尽毁于己手，积怨缠身，方寸惊乱，亲率三军攻城，誓荡平淮南，讨灭天下不臣，成大业，慰父兄。",
