    "intro": "娄圭（生卒年不详），字子伯，荆州南阳郡（治今河南南阳）人。东汉末年将领，娄圭年轻时与曹操有交情。最初在荆州北面收集部众，后归顺曹操，被任命为大将。随曹操平定冀州，南征荆州，击破马超，立有功劳，连曹操都感叹他的计谋。后来曹操和他的儿子们一起出去游玩，娄圭因言语不当，被南郡（治今湖北荆州）人习授举报，遭到曹操杀害。小说《三国演义》中，娄子伯是京兆人，隐居终南山，道号“梦梅居士”。曹操征讨马超之际，娄子伯拜访曹操，曹操以客礼待之。娄子伯教给曹操浇水结冰筑城之法，使得曹军筑起土城，娄子伯不受赏赐，随后告辞。",
