    "intro": "徐庶（公元168年—公元235年）[1]，本名徐福，字元直，豫州颍川（今河南省禹州市）人，东汉末年刘备帐下谋士，后归曹操，仕于曹魏。董卓作乱时，徐庶与石广元避难于荆州，与司马徽、诸葛亮等道友来往密切。刘备屯驻新野时，张布（？-264年），在孙休受封为琅琊王时，为左右将督。太平三年（258年），孙休即位后，张布由长水校尉迁辅义将军，封永康侯。不久，孙休听说孙綝阴谋反叛，于是暗中和张布商量计策，孙綝被杀后，左将军张布因功加封中军督。 由于孙休对张布厚加恩宠，所以张布专擅朝廷大权，多行无礼之事。",
