    "intro": "孙韶（188年－241年），字公礼，吴郡富春（今浙江杭州富阳区）人，三国时期吴国宗室、将领。孙韶的伯父孙河，本姓俞，孙策很喜爱他，便赐姓孙，将他列名孙氏家族之中。建安九年（204年），孙河被杀，孙韶统帅孙河的军队，被孙权任命为承烈校尉。后任广陵太守、偏将军。黄初二年（221年），孙权受封吴王，升任他为扬威将军，封建德侯。黄武四年（225年）十月，孙韶派遣将领高寿等人率领五百敢死士兵，从小路夜袭魏文帝曹丕的军队，曹丕大惊，高寿等人夺得其车盖而回。黄龙元年（229年），孙权称帝，任命孙韶为镇北将军。孙权后加任孙韶兼任幽州牧，假节。赤乌四年（241年），孙韶去世。",
    "source": "https://www.sanguosha.cn/index.php/pc/hero-detail-616.html",
