    "intro": "孟达（?－228年），字子度，本字子敬，因刘备的叔父名叫刘子敬，为避讳而改字。扶风郡平陵县人，东汉凉州刺史孟佗之子。本与法正一同入蜀依附刘璋，后降刘备，奉命与刘封平定上庸等地。关羽围樊城、襄阳时，拒绝出兵帮助，关羽败亡后畏惧治罪，又与刘封不和，因此率众投魏。孟达投魏后颇受曹丕宠爱，官至散骑常侍、建武将军，封平阳亭侯，领新城太守，与夏侯尚等共讨刘封。曹丕去世后，孟达又受到诸葛亮招诱，欲反曹魏而归蜀汉，最终被司马懿军击杀。",
