    "intro": "崔芙（生卒年不详），清河东武城人，崔琰侄女，曹植之妻。建安二十一年（216年），曹操晋封魏王，世子之争愈烈。时崔琰以刚直见忌，崔芙复衣锦获罪：其雅好华裳，罗绮盈箱；常服焕彩，终惹魏王之怒。虽曹植百般求情，然成命难违。罗绮遽成罪证，华裳尽作冥资。清河望族，翻作政治之祭；高门贵女，终成权力之殇。",
